solutions.naive:
class Solution:
    def maxIceCream(self, costs: list[int], coins: int) -> int:
        dp = [-10**9] * (coins + 1)
        dp[0] = 0
        for cost in costs:
            if cost <= coins:
                for c in range(coins, cost - 1, -1):
                    dp[c] = max(dp[c], dp[c - cost] + 1)
        return max(dp)

solutions.better:
class Solution:
    def maxIceCream(self, costs: list[int], coins: int) -> int:
        ans = 0
        for cost in sorted(costs):
            if cost > coins:
                break
            coins -= cost
            ans += 1
        return ans

solutions.optimal:
class Solution:
    def maxIceCream(self, costs: list[int], coins: int) -> int:
        if not costs:
            return 0
        freq = [0] * (max(costs) + 1)
        for cost in costs:
            freq[cost] += 1
        ans = 0
        for price in range(1, len(freq)):
            if freq[price] == 0:
                continue
            take = min(freq[price], coins // price)
            ans += take
            coins -= take * price
            if take < freq[price]:
                break
        return ans

